  getResdSchoolList(event, fun) {

    if (event != '' && event != null && event != undefined && event != 0) {
      if (fun == 'load') {
        if (this.studentData.SplSchl != '' && this.studentData.SplSchl != null && this.studentData.SplSchl != undefined && this.studentData.SplSchl != 0) {
          if (this.studentData.SpclTrngTyp == 1) {
            this.form.controls['SplSchl'].setValue({ value: this.studentData.ResdSchlID, label: this.studentData.ResdCenterLoca });
            this.form.controls["SplSchl"].setValidators(Validators.required);
            this.form.controls['SplSchlUdise'].setValue('');
          } else {
            this.form.controls['SplSchl'].setValue({ value: this.studentData.SplSchlID, label: this.studentData.SplSchlName });
            this.form.controls["SplSchl"].setValidators(Validators.required);
            this.form.controls['SplSchlUdise'].setValue(this.studentData.SplSchlUdise);
          }
        } else {
          this.form.controls['SplSchl'].setValue('');
          this.form.controls["SplSchl"].setValidators(Validators.required);
          this.form.controls['SplSchlUdise'].setValue('');
        }
      } else {
        this.form.controls['SplSchl'].setValue('');
        this.form.controls["SplSchl"].setValidators(Validators.required);
        this.form.controls['SplSchlUdise'].setValue('');
      }

      let json_name = 'https://d1wpyxz35bzzz4.cloudfront.net/osc_detail_master_udise.json';
      this.http.get<any>(json_name).subscribe((data) => {

        if (data) {
          var school;
          if (event == 1) {
            school = data.rstclocation;
            this.resiSchlList = school.map(l => { return { label: l.rstc_location, value: l.id }; });
          } else if (event == 2) {
            school = data.spltrainingcenter;
            this.resiSchlList = school.map(l => { return { label: l.school_name, value: l.school_id, udise: l.udise_code }; });
          } else {
            school = data.udise_36;
            this.resiSchlList = school.map(l => { return { label: l.school_name, value: l.school_id, udise: l.udise_code }; });
          }

          this.resiSchlList.sort((a, b) => {
            if (a.label < b.label)
              return -1;
            if (a.label > b.label)
              return 1;
            return 0;
          });
        }
      });
    } else {
      this.form.controls['SplSchl'].setValue('');
      this.form.controls['SplSchlUdise'].setValue('');
      this.form.controls["SplSchl"].setValidators(null);
    }
    this.form.controls["SplSchl"].updateValueAndValidity();
  }

