  checkDepartmentListLocalDB() {
    this.masterCountryList = [];
    let query = 'SELECT * FROM allCountryDetails';
    return this.sqliteDB.getDataLocalDB(query).then(country => {
      if (country.rows.length > 0) {
        let temp: any = [];
        for (var i = 0; i < country.rows.length; i++) {
          temp.push(country.rows.item(i));
        };
        this.masterCountryList = temp;

        const key = 'country_id';
        let unique_list: any[] = [...new Map(this.masterCountryList.map(item =>
          [item[key], item])).values()];

        if (this.masterCountryList.length > 0) {
          this.ooscCountryList = unique_list.map(l => { return { label: l.country_name, value: l.country_id }; });
          this.ooscCountryList.sort((a, b) => {
            if (a.label < b.label)
              return -1;
            if (a.label > b.label)
              return 1;
            return 0;
          });
        }
        this.checkStateLocalDB();
      } else {
        this.getOOSCMasterDetailsJson();
      }
    });
  }

